async *parse(input, options) {
  if (options) this.options = options;
  const stream = (this.stream = this._getStream(input || this.input));
  const zip = unzip.Parse({forceStream: true});
  const forwardError = error => zip.destroy(error);
  stream.once('error', forwardError);
  stream.pipe(zip);

  // worksheets, deferred for parsing after shared strings reading
  const waitingWorkSheets = [];

  try {
    for await (const entry of zip) {
      let match;
      let sheetNo;
      switch (entry.path) {
        case '_rels/.rels':
          break;
        case 'xl/_rels/workbook.xml.rels':
          await this._parseRels(entry);
          break;
        case 'xl/workbook.xml':
          await this._parseWorkbook(entry);
          break;
        case 'xl/sharedStrings.xml':
          yield* this._parseSharedStrings(entry);
          break;
        case 'xl/styles.xml':
          await this._parseStyles(entry);
          break;
        default:
          if (entry.path.match(/xl\/worksheets\/sheet\d+[.]xml/)) {
            match = entry.path.match(/xl\/worksheets\/sheet(\d+)[.]xml/);
            sheetNo = match[1];
            if (this.sharedStrings && this.workbookRels && this.model) {
              yield* this._parseWorksheet(iterateStream(entry), sheetNo);
            } else {
              // create temp file for each worksheet
              const temporary = await new Promise((resolve, reject) => {
                tmp.file({discardDescriptor: true}, (err, path, fd, tempFileCleanupCallback) => {
                  if (err) return reject(err);
                  return resolve({sheetNo, path, tempFileCleanupCallback});
                });
              });
              waitingWorkSheets.push(temporary);
              await pipeline(entry, fs.createWriteStream(temporary.path));
            }
          } else if (entry.path.match(/xl\/worksheets\/_rels\/sheet\d+[.]xml.rels/)) {
            match = entry.path.match(/xl\/worksheets\/_rels\/sheet(\d+)[.]xml.rels/);
            sheetNo = match[1];
            yield* this._parseHyperlinks(iterateStream(entry), sheetNo);
          }
          break;
      }
      entry.autodrain();
    }

    for (const {sheetNo, path} of waitingWorkSheets) {
      let fileStream = fs.createReadStream(path);
      // TODO: Remove once node v8 is deprecated
      // Detect and upgrade old fileStreams
      if (!fileStream[Symbol.asyncIterator]) {
        fileStream = fileStream.pipe(new PassThrough());
      }
      try {
        yield* this._parseWorksheet(fileStream, sheetNo);
      } finally {
        fileStream.destroy();
        await finished(fileStream).catch(() => {});
      }
    }
  } finally {
    stream.unpipe(zip);
    stream.destroy();
    zip.destroy();
    stream.removeListener('error', forwardError);
    for (const {tempFileCleanupCallback} of waitingWorkSheets) {
      tempFileCleanupCallback();
    }
  }
}
